/** Lowercase URL slug: diacritics stripped, non-alphanumeric runs become one "-". */
export function slugify(title: string): string {
  return title
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-|-$/g, '');
}
EOF
sed -i '' "s/import { capitalize, truncate }/import { capitalize, slugify, truncate }/" test/text.test.ts
cat >> test/text.test.ts <<'EOF'

test('slugify', () => {
  assert.equal(slugify('Hello, World!'), 'hello-world');
  assert.equal(slugify('  Ship it -- now  '), 'ship-it-now');
  assert.equal(slugify('Crème Brûlée'), 'creme-brulee');
  assert.equal(slugify('!!!'), '');
  assert.equal(slugify(''), '');
});
EOF
